/* Patient overview and preparation, scoped to synthetic browser records. */
let patientOverviewTab='overview',patientActivityFilter='all',pendingPatientTask=null;
const preparationChecks=[['sources','Read the available source information'],['gaps','Identify information that still needs checking'],['agenda','Prepare the appointment agenda']];
function patientPreparation(){const id=currentPatient().id;state.patientPreparation=state.patientPreparation||{};return state.patientPreparation[id]||(state.patientPreparation[id]={checks:{},note:'',fingerprint:null});}
function preparationFingerprint(){const p=currentPatient(),r=state.patientRecords[p.id];return JSON.stringify([p.id,p.priority,p.source,p.preference,p.action,r.note,r.version,r.revision,r.signed,r.formData,r.formApproval]);}
function preparationStatus(){const prep=patientPreparation(),stale=!!prep.fingerprint&&prep.fingerprint!==preparationFingerprint();const count=stale?0:preparationChecks.filter(([k])=>prep.checks[k]===true).length;return {stale,count,complete:count===preparationChecks.length};}
function setPreparationCheck(key,checked){if(!preparationChecks.some(([k])=>k===key)||typeof checked!=='boolean')return;const prep=patientPreparation();if(preparationStatus().stale)prep.checks={};prep.fingerprint=preparationFingerprint();prep.checks[key]=checked;const saved=save();render();document.getElementById('preparation-check-'+key)?.focus();preparationChangeFeedback(saved,'Checklist updated');}
function updatePreparationNote(value){if(typeof value!=='string'||value.length>1500)return;patientPreparation().note=value;save();refreshPreparationSaveStatus();}
function clearPreparationChecks(){const prep=patientPreparation();prep.checks={};prep.fingerprint=null;const saved=save();render();document.getElementById('clear-preparation')?.focus();preparationChangeFeedback(saved,'Checklist cleared. Agenda notes retained');}
function preparationPanel(){const prep=patientPreparation(),status=preparationStatus();return `<section class="panel preparation-panel"><div class="panel-head"><div><span class="eyebrow">BEFORE THE APPOINTMENT</span><h2>Preparation checklist</h2></div><span id="preparation-progress" role="status" class="pill ${status.complete?'green':'grey'}">${status.count} of 3</span></div><p class="fine">Your local preparation notes. Patient identity, consent and clinical facts still need their own checks.</p>${status.stale?'<p class="notice amber">The document or form changed. Recheck the preparation items against the current information.</p>':''}<div class="preparation-checks">${preparationChecks.map(([key,label])=>`<label><input id="preparation-check-${key}" type="checkbox" ${!status.stale&&prep.checks[key]?'checked':''} onchange="setPreparationCheck('${key}',this.checked)"><span>${label}</span></label>`).join('')}</div><label class="prep-note-label" for="preparation-note">Agenda notes <span>Optional · Fictional information only</span></label><textarea class="field" id="preparation-note" rows="4" maxlength="1500" oninput="updatePreparationNote(this.value)" placeholder="What do you want to clarify at this appointment?">${esc(prep.note)}</textarea><p class="fine" id="prep-note-status" role="status">${preparationSaveLabel(prep.note.length)}</p><button id="clear-preparation" class="text-btn" onclick="clearPreparationChecks()">Clear checklist</button></section>`;}
function patientLinkedTasks(){return state.tasks.map((t,index)=>({...t,index})).filter(t=>t.patientId===state.selectedPatientId);}
function patientLinkedHandovers(){return handoverDrafts().map((d,index)=>({...d,index})).filter(d=>d.patientId===state.selectedPatientId);}
function patientNextStep(){const r=state.patientRecords[currentPatient().id];if(r.note.trim()&&!r.signed)return {title:'Review the current document',detail:'Check the exact text against its source before recording local review.',target:'N',label:'Open document review'};if(r.formData&&!r.formApproval)return {title:'Finish reviewing the form',detail:'Confirm each field and review the completed form.',target:'F',label:'Continue form review'};if(r.signed)return {title:'Coordinate the follow-up',detail:'Use the reviewed source to prepare a task or handover draft.',target:'N',label:'Open reviewed document'};return {title:'Prepare for the consultation',detail:'Read the available context, check what is missing and prepare the agenda.',target:'C',label:'Open consultation'};}
function patientWorkSummary(){const r=state.patientRecords[currentPatient().id],tasks=patientLinkedTasks(),handovers=patientLinkedHandovers();return `<div class="patient-work-summary"><button onclick="nav('N')"><span>${icon('file')} Document</span><strong>${r.signed?'Reviewed locally':r.note.trim()?'Draft to review':'Not started'}</strong><small>${r.note.trim()?'Version '+r.version:'Prepare a consultation note'}</small></button><button onclick="nav('F')"><span>${icon('form')} Follow-up form</span><strong>${r.formApproval?'Approved locally':r.formData?'Review in progress':'Not started'}</strong><small>${r.formData?r.formData.filter(f=>f.reviewed).length+' of '+r.formData.length+' fields checked':'Source-linked preferences'}</small></button><button onclick="focusPatientSection('patient-follow-up')"><span>${icon('check')} Follow-up</span><strong>${tasks.filter(t=>!t.done).length} open tasks</strong><small>${handovers.length} handover ${handovers.length===1?'draft':'drafts'} · None sent</small></button></div>`;}
function focusPatientSection(id){if(!['patient-follow-up','patient-sources'].includes(id))return;patientOverviewTab='overview';render();const el=document.getElementById(id);el?.scrollIntoView?.({behavior:'smooth',block:'start'});el?.focus?.();}
function patientSourcesPanel(){const p=currentPatient();return `<section class="panel patient-sources" id="patient-sources" tabindex="-1"><div class="panel-head"><div><h2>Available context</h2><p>Patient-stated information from scripted sources.</p></div><span class="pill grey">2 sources</span></div><div class="patient-context-card"><span class="eyebrow">PATIENT PRIORITY</span><h3>${esc(p.priority)}</h3><p>${esc(p.source)}</p><button class="text-btn" onclick="showPatientSource('priority')">View source · 00:24 ${icon('arrow')}</button></div><div class="patient-context-card"><span class="eyebrow">FOLLOW-UP PREFERENCE</span><h3>${esc(p.preference)}</h3><p>${esc(p.action)}.</p><button class="text-btn" onclick="showPatientSource('preference')">View source · 01:42–02:08 ${icon('arrow')}</button></div><div class="patient-missing"><strong>Information still needed</strong><ul><li>Date of birth and NHS number not supplied</li><li>Medication and allergies not recorded</li><li>No external clinical history retrieved</li></ul><p>“Not recorded” does not mean “none”. The preparation checklist does not verify or replace these details.</p></div></section>`;}
function showPatientSource(kind){if(!['priority','preference'].includes(kind))return;const p=currentPatient();modal(kind==='priority'?'Patient-stated priority':'Follow-up preference',`<div class="handover-identity"><strong>${esc(p.name)}</strong><span>${esc(p.id)} · Scripted source</span></div>${kind==='priority'?`<p class="source-time">00:24 · Patient</p><blockquote>${esc(p.priority)}. ${esc(p.source)}</blockquote>`:`<p class="source-time">01:42 · Clinician</p><blockquote>We can ${esc(p.action.toLowerCase())} and arrange a follow-up. Which day works for you?</blockquote><p class="source-time">02:08 · Patient</p><blockquote>${esc(p.preference)} would work best.</blockquote>`}<p class="fine">This is a scripted example. No recorded audio or external clinical record was retrieved.</p>`);}
function patientFollowupPanel(){const tasks=patientLinkedTasks(),handovers=patientLinkedHandovers();return `<section class="panel patient-followup" id="patient-follow-up" tabindex="-1"><div class="panel-head"><div><h2>Follow-up & ownership</h2><p>Only work explicitly linked to this patient.</p></div><button class="text-btn" onclick="openPatientTaskComposer()">${icon('plus')} Add task</button></div>${tasks.length?tasks.map(t=>`<div class="patient-task-row"><input id="patient-task-check-${t.index}" type="checkbox" aria-label="Mark ${esc(t.text)} ${t.done?'open':'complete'}" ${t.done?'checked':''} onchange="setTaskDone(${t.index},this.checked,this.id)"><div><button class="task-title ${t.done?'patient-task-done':''}" onclick="openTaskDetails(${t.index})">${esc(t.text)}</button><p>${esc(t.owner)} · ${esc(taskDateLabel(t.dueDate))}${t.done?' · Completed':''}</p></div></div>`).join(''):'<div class="patient-inline-empty"><p>No patient-linked tasks yet.</p><span>Shared team tasks are available on the task board.</span></div>'}<div class="patient-handover-list"><h3>Handover drafts</h3>${handovers.length?handovers.map(d=>`<button class="patient-handover-row" onclick="showHandoverDraft(${d.index})"><span><strong>For ${esc(d.recipient)}</strong><small>Note v${esc(d.sourceVersion)} · Not sent${handoverSourceChanged(d)?' · Source changed':''}</small></span>${icon('arrow')}</button>`).join(''):'<p class="fine">No handover drafts for this patient.</p>'}</div><div class="patient-followup-actions"><button ${!state.signed?'disabled':''} onclick="openHandoverComposer()">Prepare handover</button><button onclick="showPatientTasks(state.selectedPatientId)">View this patient’s tasks</button><button onclick="nav('T')">Team task board</button></div>${!state.signed?'<p class="fine">A signed local document is needed to prepare a source-linked handover.</p>':''}</section>`;}
function openPatientTaskComposer(){const p=currentPatient();pendingPatientTask={patientId:p.id};modal('Add task for '+p.name,`<div class="handover-identity"><strong>${esc(p.name)}</strong><span>${esc(p.id)} · Patient-linked administrative task</span></div><form id="patient-task-composer" onsubmit="event.preventDefault();savePatientTask(this)">${taskEditorFields()}</form>`,`<button onclick="pendingPatientTask=null;closeModal()">Cancel</button><button class="primary" type="submit" form="patient-task-composer">Save task</button>`);document.getElementById('task-description')?.focus?.();}
function savePatientTask(form){const pending=pendingPatientTask;if(!pending||pending.patientId!==state.selectedPatientId)return;const values=readTaskEditor(form);if(!values)return;state.tasks.push({...values,patientId:pending.patientId,done:false});pendingPatientTask=null;const saved=audit(state.selectedPatientId+': patient-linked local task created.');closeModal();render();toast(saved?'Task saved for this patient.':'Patient task remains in this tab only. Saving failed.');}
function patientActivityItems(){const p=currentPatient(),r=state.patientRecords[p.id];const notes=r.history.map((h,index)=>({kind:'document',index,title:'Document · Version '+h.version,status:h.status==='Signed in demo'?'Reviewed locally':h.status,at:h.at||null}));const forms=(state.formUi?.[p.id]?.history||[]).map((h,index)=>({kind:'form',index,title:'Follow-up form · Version '+h.version,status:h.status,at:h.snapshot.at||null}));const handovers=patientLinkedHandovers().map(h=>({kind:'handover',index:h.index,title:'Handover draft · Note v'+h.sourceVersion,status:'For '+h.recipient+' · Not sent',at:h.createdAt||null}));return [...notes,...forms,...handovers].filter(x=>patientActivityFilter==='all'||patientActivityFilter===x.kind).sort((a,b)=>(Date.parse(b.at)||0)-(Date.parse(a.at)||0));}
function patientActivityDate(at){if(!at||!Number.isFinite(Date.parse(at)))return 'Time not recorded';return new Intl.DateTimeFormat('en-GB',{dateStyle:'medium',timeStyle:'short',timeZone:'Europe/London'}).format(new Date(at));}
function patientActivityPanel(){const rows=patientActivityItems();return `<section class="panel patient-activity"><div class="panel-head"><div><h2>Saved activity</h2><p>Document copies, form versions and handover drafts for ${esc(currentPatient().name)}.</p></div><span class="pill grey">Local history</span></div><div class="segmented" aria-label="Filter patient activity">${[['all','All activity'],['document','Documents'],['form','Forms'],['handover','Handovers']].map(([id,label])=>`<button aria-pressed="${patientActivityFilter===id}" onclick="patientActivityFilter='${id}';render()">${label}</button>`).join('')}</div>${rows.length?`<ol class="patient-activity-list">${rows.map(x=>`<li><span class="activity-symbol">${icon(x.kind==='document'?'file':x.kind==='form'?'form':'people')}</span><div><h3>${esc(x.title)}</h3><p>${esc(x.status)}</p><small>${esc(patientActivityDate(x.at))}${x.at?' · UK time':''}</small></div><button onclick="showPatientActivity('${x.kind}',${x.index})">View snapshot</button></li>`).join('')}</ol>`:'<div class="workspace-empty"><span class="empty-symbol">'+icon('clock')+'</span><h3>No saved activity in this view</h3><p>Saved draft copies, reviewed documents, form versions and handover drafts appear here. The current draft is available in the note editor, even if no version copy has been retained.</p><button onclick="nav(\'N\')">Open current document</button></div>'}<p class="fine">These are browser-local copies, not an EPR history or a tamper-evident audit log. Entries without timestamps remain undated.</p></section>`;}
function showPatientActivity(kind,index){if(!Number.isInteger(index)||index<0)return;const p=currentPatient();if(kind==='handover'){const d=handoverDrafts()[index];if(d?.patientId===p.id)showHandoverDraft(index);return;}let body,title;if(kind==='document'){const h=state.patientRecords[p.id].history[index];if(!h||h.patientId&&h.patientId!==p.id)return;title='Document snapshot · Version '+h.version;body=`<p class="fine">${esc(h.status==='Signed in demo'?'Reviewed locally':h.status)} · ${esc(patientActivityDate(h.at))}</p><pre class="review-copy">${esc(h.text)}</pre>`;}else if(kind==='form'){const h=state.formUi?.[p.id]?.history[index];if(!h||h.snapshot.patientId!==p.id)return;title='Form snapshot · Version '+h.version;body=`<p class="fine">${esc(h.status)} · ${esc(patientActivityDate(h.snapshot.at))}</p>${h.snapshot.fields.map(f=>`<div class="history-field"><strong>${esc(f.label)}</strong><p>${esc(f.value)}</p><small>Source value: ${esc(f.original)}</small></div>`).join('')}`;}else return;modal(title,`<div class="handover-identity"><strong>${esc(p.name)}</strong><span>${esc(p.id)} · Retained local snapshot</span></div>${body}<p class="fine">Read-only view of this local copy. No EPR submission or delivery is implied.</p>`);}
recordPage=function(){const p=currentPatient(),next=patientNextStep();return pageHeading('Patient workspace',p.visit,`<button onclick="showPatientSource('priority')">${icon('book')} Read source</button><button class="primary" onclick="nav('C')">${icon('mic')} Open consultation</button>`)+patientStrip()+patientWorkspaceTabs()+`<div class="patient-appointment-bar"><span>${icon('calendar')} <strong>${esc(p.time)} · 13 October 2026</strong><span>Example clinic</span></span><button class="text-btn" onclick="nav('patients')">Clinic list ${icon('arrow')}</button></div>${patientWorkSummary()}<div class="patient-overview-switch segmented" aria-label="Patient overview view"><button aria-pressed="${patientOverviewTab==='overview'}" onclick="patientOverviewTab='overview';render()">Overview & preparation</button><button aria-pressed="${patientOverviewTab==='activity'}" onclick="patientOverviewTab='activity';render()">Saved activity</button></div>${patientOverviewTab==='activity'?patientActivityPanel():`<div class="patient-overview-grid"><section>${patientSourcesPanel()}${patientFollowupPanel()}</section><aside><section class="panel patient-next-action"><span class="eyebrow">NEXT ADMINISTRATIVE STEP</span><h2>${esc(next.title)}</h2><p>${esc(next.detail)}</p><button class="primary wide" onclick="nav('${next.target}')">${esc(next.label)} ${icon('arrow')}</button></section>${preparationPanel()}</aside></div>`}`;};
const patientUiPriorSelect=selectPatient;
selectPatient=function(id){if(!demoPatients.some(p=>p.id===id))return;pendingPatientTask=null;patientOverviewTab='overview';patientActivityFilter='all';return patientUiPriorSelect(id);};
render();

function preparationSaveLabel(length){return (storageSaveFailed?'Not saved · This tab only':'Kept in this browser')+' · '+length+'/1500 characters';}
function refreshPreparationSaveStatus(){const el=document.getElementById('prep-note-status');if(el)el.textContent=preparationSaveLabel(state.patientPreparation?.[state.selectedPatientId]?.note?.length||0);}

function preparationChangeFeedback(saved,action){toast(saved?action+'. Saved in this browser.':action+' in this tab only. Saving failed; use the save recovery options.');}
